globalThis.ANDE_CHUNKS["c4a174c2b304ed256105def98fb39d5c6e0dab4ab6361b182dd505443451e3df"] = [{"id":"shlab:7630804567996008754","sourceKey":"shlab","company":"上海AI实验室","title":"【27届留用实习生】-品牌内容运营-战略规划部","city":"上海","category":"运营类","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7630804567996008754?mode=campus","duty":"1. 负责协助实验室视频号、公众号小红书等官方账号内容制作及日常运营；\n2. 开展视频策划制作、视觉设计等工作；\n3. 负责日常稿件文案撰写；\n5. 负责协助进行内外部来访接待事项；\n6. 协助团队开展其他日常工作。","requirements":"1. 本科及以上学历，新闻传播、中文、人工智能相关专业优先；\n2. 较好的学习能力，能熟练使用AI工具，包括语言、图片、视频等的生成式AI工具；\n3. 较好的文字功底，较好的审美能力；\n4. 目标导向，逻辑清晰，有较好的执行力和抗压能力；\n5.  对人工智能行业有认知与兴趣，能读懂前沿科研成果；\n6. 有海外品牌传播、内容运营经验优先。\n","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab:7630804720588130598","sourceKey":"shlab","company":"上海AI实验室","title":"【27届留用实习生】-品牌活动-战略规划部","city":"上海","category":"运营类","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7630804720588130598?mode=campus","duty":"1. 负责协助实验室大型活动、会议组织等相关工作；\n2. 根据活动需要开展摄影摄像、后期、视觉设计等工作；\n3. 负责协助进行内外部来访接待事项；\n4. 协助团队开展其他日常工作。","requirements":"1. 本科及以上学历，新闻传播、设计类或人工智能相关专业优先;\n2. 较好的学习能力，能熟练使用AI工具，包括语言、图片、视频等的生成式AI工具；\n3. 较好的沟通协调能力，较好的审美能力；\n4. 目标导向，逻辑清晰，有较好的执行力和抗压能力；\n5. 对人工智能行业有认知与兴趣，能读懂前沿科研成果。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab:7643743598476118278","sourceKey":"shlab","company":"上海AI实验室","title":"【27届留用实习生】-高校合作专员-浦江书院","city":"上海","category":"职能类","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7643743598476118278?mode=campus","duty":"我们不仅是前沿技术的攻坚者，更是连接顶尖高校与国家战略需求的“战略枢纽” 。在这里，你将深度参与顶尖联培博士项目（已录取逾千名顶尖学子）及全生命周期人才社区的构建 。\n【你将获得的硬核成长】\n这绝不是一个刻板的行政岗位，而是一个极具挑战性的“泛化能力孵化器”。你将在这里锻炼出：\n超级多线程管理（Multi-tasking）： 跨界调度高校、导师及政府多方资源 。 \n顶级圈层破局力： 与国内外顶尖科学家、C9高校高层直接对话 。 \n战略与运营闭环能力： 体验从战略协议签署、项目落地、品牌策划到数据复盘的全链条商业/科研管理逻辑 。 \n\n多维战略推进： 协助推进与C9及重点985高校的战略合作，负责日常高频、高质的组织座谈与资源对接 。  \n联培生态运营： 全流程参与联培博士生的招生、导师协调及日常资源保障，运营“浦江书院”人才社区，打造有温度的品牌活动 。  \n品牌与宣讲落地： 主导高校开放","requirements":"学历背景： 硕士及以上学历；极度欢迎人工智能/计算机+管理学/金融学/教育学等跨学科复合背景人才 。  \n\n核心特质： \n强悍的并发处理能力： 具备优秀的项目多线程管理意识，能在快节奏、多任务环境下保持清晰的逻辑 。  \n出色的沟通与资源整合力： 具备情商与同理心，能听懂科学家与高校管理层的双重语言 。  \n结果导向与自驱力： 面对未知具备强大的泛化解决问题能力，乐于自我迭代 。  \n\n加分项： 在校期间有大型项目统筹、名企实习或高校社团核心管理经验者优先。 ","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab:7644449359132739876","sourceKey":"shlab","company":"上海AI实验室","title":"【27届留用实习生】-项目经理人-战略规划部","city":"上海","category":"战略类","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7644449359132739876?mode=campus","duty":"项目经理人的核心使命是在科学世界和产业世界之间架起桥梁，发现并推动具有战略突破潜力的创新项目，需要通过系统的价值发现、精准的团队评估、深度的项目共创，连接顶尖科学家、产业领袖和政策制定者，推动中国科技创新的战略突破。\n应届生通道的核心定位是培养早期科研投资人。入职后将在资深项目经理人的带教下，从独立承担具体方向的调研评估开始，逐步过渡到独立负责项目全程跟进，直至主导某一领域的战略布局。首年的核心任务是建立判断框架——形成对「好科研、好团队、值得推进」的独立判断标准，并在实践中持续校准。\n\n主要职责\n1. 判断框架建立\n通过大量文献研读、一线拜访和项目跟进，逐步形成对优质科研团队和创新项目的独立判断标准\n将个人认知成长过程结构化沉淀，参与完善项目经理人评估方法论\n2. 战略级技术趋势研判\n深度追踪 AI for Science、大模型、具身智能等前沿方向，独立完成技术调研，输出有明确判断的分","requirements":"任职要求\n博士在读 / 27届优先（特别优秀者可放宽至硕士），人工智能、计算机、物理、化学、材料、生物、医学等理工科专业优先；文理兼备、具有跨学科研究背景者亦欢迎\n以下任一方向的经历将显著加分：\n1. 科研协调：在课题组中承担过跨学科合作或项目协调角色，而不仅限于独立科研执行\n2. 项目评估：参与过早期项目评估、孵化器或学生创业，具备识别潜力项目和团队的实战经验\n3. 产业实习：在高科技企业从事过 R&D 支持、战略调研或技术评估类工作\n4. 独立研究：有独立完成深度调研报告、行业研究或技术白皮书的经历\n5. 核心能力要求：\n能快速获取陌生领域核心知识，读懂专业文献，并以清晰、非专业化的语言准确表达复杂技术概念\n具备结构化分析能力，能从复杂信息中抽象核心问题，善于系统性拆解而非罗列信息\n对研究团队和项目的价值判断有主动探究的冲动，能在不确定条件下驱动自我独立决策\n综合素质要求：\n对科学本身","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab:7673323212219107635","sourceKey":"shlab","company":"上海AI实验室","title":"【实习】AI数据管理-数据平台中心","city":"上海","category":"","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7673323212219107635?mode=campus","duty":"我们是AI数据交付的核心枢纽，连接「需求方—数据方案—供应商交付」全链路。你将深度参与AI训练数据的全生命周期管理，负责从需求拆解、SOP制定、供应商交付管理到质量验收的完整闭环，在实践中掌握大规模AI数据生产的核心逻辑与项目管理方法。\n\n岗位职责\n1. 数据方案与SOP建设\n- 参与AI训练数据项目全流程：需求分析、方案设计、进度跟进、交付验收；\n- 主导或协助制定项目SOP（标准作业程序），沉淀可复用的流程规范与验收标准；\n- 编制需求文档、解决方案说明书及数据验收规范，推动流程标准化与效率提升。\n2. 供应商交付管理\n- 负责供应商全生命周期协同：调研筛选、样例评估、交付跟进、质量验收、问题闭环；\n- 搭建供应商交付数据台账，监控交付及时率、一次验收合格率、返修率等核心指标，定期输出统计分析报告；\n- 建立交付异常预警机制，对进度偏差与质量波动进行数据归因，识别瓶颈并推动改进闭环；\n","requirements":"1. 硬性要求\n- 学历：本科及以上在读，理工科专业优先；\n- 周期：至少4个月，每周4天及以上出勤；\n- 地点：上海市徐汇区国际传媒港L1（线下办公）。\n2. 核心能力（优先项）\n- 流程建设：能梳理复杂事务逻辑，输出标准化操作规范，推动流程固化；\n- 统计分析：对数据敏感，擅长通过数据发现问题、评估质量、优化流程；\n- AI应用：熟练使用AI工具辅助分析、文档处理或代码生成，了解AI数据生命周期（采集→清洗→标注→验收→入库）；\n- 技术基础：掌握Python，能处理结构化数据（CSV/Excel等）。\n3. 加分项\n- 有数据项目运营、供应商管理或科研数据处理经验者优先；\n- 了解机器学习/深度学习基础概念，有PyTorch/TensorFlow使用经验者优先。\n\n你将获得：\n- 系统化的AI数据项目管理与供应商协同实战经验；\n- 数据交付流程建设、质量管控与统计分析的方法论；\n- ","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab:7673347399540738323","sourceKey":"shlab","company":"上海AI实验室","title":"【实习】具身智能（场景生成、物理仿真、后训练）-物理智能中心","city":"上海","category":"","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7673347399540738323?mode=campus","duty":"本岗位目前有 Real2Sim2Real与具身场景生成、液体/柔体/触觉等多模态物理仿真、WAM/VLA的后训练(RLFT)与训测工具链 三条方向,同学投递后会根据背景与意愿分配符合条件的方向。\n\n岗位职责：\n1、参与具身智能领域 Real2Sim2Real 相关研究与工具链建设,研究具身可交互场景生成,并实现具身Sim2Real闭环验证;\n2、探索基于 VLM 等的自动化仿真场景生成以及生成式仿真轨迹数据合成等领域,构建全新且多样化的机器人应用场景,推动合成数据价值探索与应用落地;\n3、探索液体、柔体物理仿真建模,触觉等多模态仿真相关领域,以及与 VLA 等模型的结合应用;\n4、参与 WAM/VLA/具身智能体等方向研究,尤其是模型的 RLFT 等方向,协助后训练与评测工作,参与构建模型 RL 训测工具链。\n","requirements":"1、计算机、人工智能、机器人等相关专业，本科以上学历（研究生优先），具备扎实的图形学 / 物理仿真建模 / 强化学习基础,有相关学术或项目成果者优先;\n2、熟悉常用的计算机视觉、3D、机器人仿真(Isaac Sim / Isaac Lab、Genesis、SAPIEN、MuJoCo、Gym 等),熟练 Isaac Sim / Isaac Lab者优先;\n3、熟悉强化学习核心算法(如 PPO、GRPO 等),具备具身 VLA、WAM 等模型的后训练或机械臂操作相关经验者优先;\n4、对机器人、具身智能有浓厚兴趣,在 AIGC、机器人仿真 / 真机部署等方向有相关经验者优先;\n5、具备良好的工程能力和团队协作能力,对技术充满热情,能够配合团队需求落地相关技术;\n6、在 SIGGRAPH、NeurIPS、ICLR、ICML、CVPR、RSS、CoRL、ICRA、RAL 等机器学习 / 机器人会议或","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab:7673348635257784626","sourceKey":"shlab","company":"上海AI实验室","title":"【实习】具身仿真数据实习生 -物理智能中心","city":"上海","category":"工程通道","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7673348635257784626?mode=campus","duty":"1. 研究多样化的机器人操作场景搭建（机械臂、灵巧手、移动底盘等），设计物体交互的逻辑与剧本。\n2. 研究并设计高效的视觉与轨迹数据合成策略，包括场景布局自动随机化、物理属性扰动以及多模态传感器仿真（RGB/D/触觉），分析数据分布对下游策略性能的影响。\n3. 配合算法团队，分析合成数据在真实机器人上的泛化性瓶颈，提出改进数据生成策略的学术方案。\n","requirements":"1. 机器人、自动化、计算机等相关专业在读本科及以上学历，了解机器人学基础，可实习至少三个月。\n2. 熟练使用 Isaac Sim 或同类型仿真器，能用 Python 编写场景脚本与数据导出流程。\n3. 具备良好的实验记录与分析习惯，能系统性地比较不同数据生成策略的效果。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab:7673464279908190510","sourceKey":"shlab","company":"上海AI实验室","title":"【实习】AI网络攻防能力评测算法-安全基模中心","city":"上海","category":"","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7673464279908190510?mode=campus","duty":"参与大模型及智能体攻防评测体系建设，专注于设计系统化的网络安全评测方法，构建自动化攻防评测基准，探索AI安全能力边界的量化与度量，推动“评测驱动安全演进”的技术闭环落地。\n\n岗位职责\n1. 评测体系设计与构建：针对大模型、智能体的安全攻防能力，设计并构建面向渗透测试、安全编码、安全运营等场景的评测基准与数据集，建立多维度的安全能力评估体系。\n2. 自动化攻防评测环境开发：设计并开发自动化红蓝对抗评测基准，实现从环境构建、自动化攻击模拟到防御效能评估的全流程工程化闭环。\n3. 能力边界分析与评测报告输出：持续对标业内头部模型与安全Agent产品，通过定量评估与定性分析识别攻防能力差距，输出深度评估报告，驱动模型与Agent架构策略的双向优化。","requirements":"1. 本科及以上学历在读（研究生优先），计算机科学、人工智能、网络空间安全、信息安全、数学等相关专业。\n2. 有大模型/智能体攻防经验或相关安全实践项目经历，熟悉智能体系统架构。\n3. 参与过有影响力的开源安全项目开发，或在ACM/ICPC、Kaggle、CTF等高水平竞赛中取得优异成绩。\n4. 熟悉自动化攻防工具链（如自动化扫描、Fuzzing、漏洞利用框架等）或AI安全评测平台建设经验。\n5. 实习时间：每周出勤≥4天，能连续实习6个月及以上者优先。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab:7674919310473431306","sourceKey":"shlab","company":"上海AI实验室","title":"【实习】Agent算法实习生-技术平台中心","city":"上海","category":"","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7674919310473431306?mode=campus","duty":"1、前沿算法研究：研究大模型在垂直行业场景下的长链条规划、复杂推理与自我纠错机制；\n2、行业项目落地：结合垂直行业实际业务，将研究成果应用于专家级工作流 Agent 的搭建与优化，解决幻觉与长距离依赖痛点；  \n3、评测与数据构建：构建行业专属的复杂 Agent Task Benchmark 与高质量 Agent 轨迹数据集；  \n4、学术与工程交付：将具有普适性的创新点撰写并发表至人工智能顶级会议（ACL / EMNLP / NeurIPS / ICLR 等），同时完成核心代码在项目中的上线。","requirements":"1、计算机、AI 相关专业在读研究生，具备扎实的 Python 编程功底与大模型开发经验；  \n2、深入理解 Agent 核心组件（Skill/RAG/Memory/Tool-use），有垂直行业大模型或复杂工作流开发经验；\n3、具备工程落地意识，重视算法在真实场景中的效果提升；\n4、实践动手能力强，有ACMICPC、NOI/IOI、Top Coder、Kaggle等高水平比赛获奖经历者优先；\n5、优秀的英文文献阅读与论文写作能力，有顶会（一作或主作）发表记录者优先；","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab:7674925567683250474","sourceKey":"shlab","company":"上海AI实验室","title":"【实习】Agent算法研究（工程智能）-技术平台中心","city":"上海","category":"","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7674925567683250474?mode=campus","duty":"1. 前沿算法研究：研究大模型 Agent 在复杂专业任务中的长链条规划、推理决策、工具学习、自我纠错与强化学习方法；\n2. 专业场景落地：面向工程设计、仿真与优化等真实场景，参与专家级工作流 Agent 的研发与效果优化；\n3. 评测与数据构建：参与复杂 Agent 任务评测、高质量轨迹数据及相关训练与验证体系建设；\n4. 学术与工程交付：推动具有普适性的研究成果形成高水平论文，并完成核心算法的工程实现与应用验证。","requirements":"1. 计算机、人工智能、自动化、机械、航空航天或相关专业在读本科高年级、硕士或博士，具备扎实的 Python 编程与机器学习基础；\n2. 具备人工智能、计算机或相关交叉领域顶级会议/顶级期刊论文发表经历，原则上应为一作或主要贡献者，并能够独立推进研究与论文写作；\n3. 熟悉大语言模型及 Agent 相关技术，对 Planning、Reasoning、Tool-use、Memory、RAG、Skill 或多智能体中的一个或多个方向有实践经验；\n4. 具备较强的算法实现和实验能力，能够独立完成论文阅读、方法复现、问题分析与迭代优化；\n5. 具备工程落地意识，关注算法在真实复杂任务中的有效性、稳定性和可复现性；\n6. 有强化学习、科学计算、工程仿真、设计优化或专业软件智能体相关经验者优先；\n7. 具备良好的英文文献阅读、技术写作和团队协作能力；有高水平算法竞赛、Kaggle 或有影响力的开源项目","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab:7674927080220461358","sourceKey":"shlab","company":"上海AI实验室","title":"【实习】科学智能算法实习生（智能复杂系统方向）-天文与地球科学组","city":"上海","category":"工程通道","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7674927080220461358?mode=campus","duty":"1、参与复杂生命与环境系统相关的 AI4Science 研究，探索 AI 在科学问题中的建模与预测能力。\n2、参与多模态科学数据（时空数据、环境数据、组学数据等）的整理、分析与建模工作。\n3、参与科学基础模型（Foundation Model）在科学场景中的研究与应用。\n4、探索 AI 驱动的科学分析与发现方法，研究模型在复杂系统中的理解、推理与泛化能力。\n5、与 AI、物理、生命科学等交叉背景成员合作，参与相关研究系统与平台建设。","requirements":"1、硕士及以上学历，数学、物理、计算机、人工智能等相关专业；可连续实习3个月及以上。\n2、对复杂系统建模、AI 驱动科学发现方向感兴趣。\n3、具备一定的编程、建模或科研经验，熟悉 Python、PyTorch 等工具者优先。\n4、具备机器学习、科学计算、多模态数据分析或时空数据建模相关经验者优先。\n5、在AI/CV/科学计算领域发表过顶会论文或期刊论文。加分项： AI4Science、Scientific ML、复杂系统模拟或科研项目经历者优先。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab:7675371900402436403","sourceKey":"shlab","company":"上海AI实验室","title":"【实习】智能体攻防算法工程师（渗透测试方向）-安全可控任务部","city":"上海","category":"","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7675371900402436403?mode=campus","duty":"1. 负责智能体驱动的自动化渗透测试框架研发。 将渗透测试全流程（信息收集、攻击面分析、漏洞探测与验证、利用链构造、权限提升、横向移动、后渗透与痕迹分析）抽象为可被大模型调度的任务规划与决策流程，完成 Nmap、Burp Suite、sqlmap、Nuclei、Xray、Metasploit、dirsearch 等工具的能力抽象与接口标准化（Function Calling / MCP），解决工具调用、输出结构化解析、长程状态维护、上下文压缩与决策回溯等核心工程问题。\n2. 在授权范围内的真实业务系统与实网攻防演练中验证框架能力，系统性分析失败案例（工具误用、路径漏判、幻觉利用链等），反哺提示策略、工具链与模型训练的持续优化。\n3. 负责渗透测试智能防御框架的研发。 基于攻击侧沉淀的攻击链知识与轨迹数据，构建自动化防御能力：攻击意图识别与异常行为建模、检测规则与 WAF 策略的自动生成与优","requirements":"1. 本科及以上学历，硕博优先，计算机科学、信息安全、网络空间安全、软件工程或相关专业背景优先；能保证每周到岗 4 天及以上、连续实习 6 个月以上，27 届毕业生优先；\n2. 具备扎实的渗透测试实战功底（本岗位核心要求）：深入理解 Web 漏洞（SQL 注入、SSRF、反序列化、命令执行、越权与业务逻辑漏洞等）与内网渗透（横向移动、权限提升、域安全）的原理与利用手法，熟练使用主流渗透工具并理解其底层机制，具备独立完成完整攻击链的能力；\n3. 具备良好的编程与工程能力，熟练使用 Python，能够独立编写 POC / EXP、工具封装层与自动化框架；了解 Docker、Linux 与常见中间件的部署与隔离方案；\n4. 了解大模型与智能体技术基础：理解 Prompt 工程、Function Calling、ReAct / Reflexion 等 Agent 范式，熟悉 LangChain、L","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab:7675374669662357801","sourceKey":"shlab","company":"上海AI实验室","title":"【实习】医疗生成模型 / 患者轨迹建模实习生 - 医学智能中心","city":"上海","category":"","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7675374669662357801?mode=campus","duty":"1. 围绕患者状态预测、状态转移建模及序列决策开展研究，主要研究内容：\n  a. 探索基于扩散模型的患者状态转移方法，包括条件扩散模型、自回归扩散模型等。\n  b. 研究医疗干预对患者未来状态和临床结局的影响。\n  c. 研究因果推断与反事实建模，以区分治疗效果与观察性数据中的相关性。\n2. 主要负责相关算法的实现、模型的训练、实验设计及效果评估，根据实验结果优化模型和技术方案。\n3. 能对实际问题进行抽象和拆解，把具体应用场景转化为可实现、可验证的算法问题，依次进行实验设计，问题探究并总结实验结论。\n4. 跟踪前沿论文，参与论文、开源项目和技术成果产出。","requirements":"1. 计算机、人工智能、数学、统计学、自动化、生物医学工程等相关专业博士在读；具备相关项目经验可放宽要求。\n2. 熟悉相关技术理论及框架，包括但不限于回归/条件/奖励引导扩散模型，微分方程，病人轨迹，世界模型。有具体项目搭建经验者优先。\n3. 熟悉医疗相关数据集，如MIMIC，EHR等。\n4. 具备较强的学习能力和科研兴趣，能够快速阅读论文、理解方法并进行复现和改进。\n\n加分项：\n1. 具有较好的数学基础，能够理解机器学习、扩散模型中的基本公式与目标函数；\n2. 对强化学习，如CQL，DQN等有所了解；\n3. 对因果推断与反事实预测等有所了解；\n4. 具有较强的问题抽象与逻辑表达能力，能够将一个复杂问题清晰、准确地表达和解释；\n5. 有相关科研项目、论文复现、开源项目或论文发表经历。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab:7675616313071552804","sourceKey":"shlab","company":"上海AI实验室","title":"【实习】大模型可解释性算法-医学智能中心","city":"上海","category":"","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7675616313071552804?mode=campus","duty":"1. 开展大模型可解释性、表示学习和模型机制分析相关研究，探索提升模型透明性与可信性的技术方法。\n2. 负责模型训练、实验系统搭建与算法优化，包括数据处理、模型微调和训练框架实现。\n3. 设计模型评估方法，分析模型表示、解释能力和鲁棒性表现。\n4. 跟踪前沿研究进展，复现和改进相关方法，探索创新研究方向。\n5. 参与论文、技术报告及开源项目建设，推动研究成果落地。","requirements":"1. 计算机科学、人工智能、数学、自动化或相关专业硕士及以上学历；特别优秀者可适当放宽。\n  2. 熟悉 Transformer 和大语言模型的基本原理，对模型训练、内部表示或可解释性研究有较深入的理解。\n  3. 具备扎实的机器学习基础，熟练使用 Python、PyTorch 和 Linux，能够独立完成模型训练、实验分析与问题诊断。\n  4. 具备良好的科研能力，能够进行文献调研、实验设计、结果分析和技术写作，对实验结论保持严谨审慎。\n  5. 对大模型可解释性研究有强烈兴趣，具备良好的沟通能力、协作意识和自主推进能力。\n\n加分项\n  1. 具有大模型训练、强化学习、RLHF、表示学习、模型评估或可解释性研究经验。\n  2. 熟悉模型内部激活提取、activation intervention、probing、representation analysis 等方法。\n  3. 具有分布","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab:7675616474254412095","sourceKey":"shlab","company":"上海AI实验室","title":"【实习】大模型Agent审计与自进化算法-医学智能中心","city":"上海","category":"","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7675616474254412095?mode=campus","duty":"1.开展大模型Agent评测、审计与自进化研究，探索Agent能力评估与持续优化关键技术。\n2.研发Agent评测与审计系统，负责执行轨迹采集、自动化评测和实验平台建设。\n3.设计过程级与结果级评测方法，分析Agent在规划、工具使用、推理、效率和鲁棒性等方面的表现。\n4.探索基于轨迹、环境反馈和交互数据的自进化方法，推动Agent能力持续提升。\n5.跟踪Agent前沿技术，参与论文、开源项目和技术成果产出。","requirements":"1.计算机科学、人工智能、数学、自动化或相关专业硕士及以上学历；特别优秀者可适当放宽。 \n2.熟悉Transformer、大语言模型和LLM Agent的基本原理，对Agent推理、工具调用、任务规划或模型训练有较深入的理解。 \n3.具备扎实的机器学习基础，熟练使用Python、PyTorch和Linux，能够独立完成模型训练、Agent实验、数据分析与问题诊断。 \n4.具备良好的科研能力，能够进行文献调研、实验设计、Benchmark构建、结果分析和技术写作，对实验结论保持严谨审慎。 \n5.具有较强的科研探索能力，对LLM Agent、Agent Evaluation 或 Recursive Self-Improving Agent等方向保持持续关注，能够独立提出问题并推动研究落地等方向有浓厚兴趣，具备良好的沟通协作能力和自主推进能力。 \n\n加分项 \n1. 具有LLM Agent、大模型","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab:7675929796249372974","sourceKey":"shlab","company":"上海AI实验室","title":"【实习】网络安全数据研究-数据平台中心","city":"上海","category":"","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7675929796249372974?mode=campus","duty":"1、深入研究软件、设备、系统、网络协议等某领域或多领域的安全漏洞，利用逆向工程、模糊测试、静态/动态代码分析等技术，并制作Docker环境；\n2、探索应用大语言模型（LLM）技术于Web与二进制领域的复杂漏洞挖掘，结合专业知识，设计构建相关自动化数据工具/流程；\n3、研究前沿攻防技术，跟踪国内外安全动态与漏洞披露信息，复现漏洞，研究攻击手法和防御技术，持续提升的安全研究能力；\n4、参与相关项目或课题，推动漏洞研究能力的价值转化。","requirements":"1、计算机科学、信息安全或相关领域本科及以上学历在读；\n2、精通至少一种编程语言（如C/C++、Python、Ruby等），熟悉X86或ARM汇编指令，有扎实的编程基础，熟练掌握逆向工程、二进制分析工具（IDA Pro、GDB等）和常见漏洞利用技术；\n3、具有成功的漏洞挖掘与利用案例，有CVE编号的漏洞报告者优先；\n4、具备出色的逻辑思维和问题解决能力，善于创新，能够独立进行复杂安全问题的研究，能够清晰地解释技术细节，撰写高质量的技术报告；\n5、对网络安全及人工智能感兴趣，有热情和自我驱动力；\n6、参加过天府杯、Pwn2Own等赛事，并成功攻破目标，或在有影响力的业界会议（学术/工业）上发表论文者优先考虑。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab:7675983396304685322","sourceKey":"shlab","company":"上海AI实验室","title":"【实习】多模态脑科学AI算法实习生-生命科学智能中心","city":"上海","category":"科研通道","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7675983396304685322?mode=campus","duty":"研发基于多模态脑科学/脑疾病数据的计算与推理模型，包括且不限于各种模态下的图像，电生理，脑网络，基因的数据表征方法和下游任务分析，依托大模型与智能体开发推理框架。研究方向包括且不限于脑机理发现、脑机接口以及抑郁症、阿尔茨海默症、帕金森病等相关课题。","requirements":"1、人工智能、计算机类或生物医学工程类相关专业，硕士或博士在读，研究领域在以下领域之一，包括人工智能、神经科学、生物信息、神经影像分析、或者计算机视觉等方面；\n2、有扎实的数理基础和良好的逻辑思维能力，有深度学习算法框架使用经验，能够熟练阅读英文论文，具有一定的科学技术研究能力，有开展跨学科研究的学习和问题解决能力；\n3、良好的编程能力，熟悉Python, C++, Cuda, Pytorch, Linux下常用指令；\n4、有计算机、神经影像、生物信息学、神经科学等领域期刊或会议论文发表或者大赛获奖经历者优先。大于6个月长期实习者优先。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab:7676045576878639411","sourceKey":"shlab","company":"上海AI实验室","title":"【实习】科研产品运营-产品规划中心","city":"上海","category":"","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7676045576878639411?mode=campus","duty":"1、协助开展 AI 科研平台的产品运营工作，与生态合作、产品及研发团队配合，推动高校及科研场景中的用户增长和产品落地；\n2、深入了解研究生、高校教师及课题组在文献阅读、论文写作、实验数据处理等环节的需求，参与用户访谈、需求收集和反馈整理；\n3、协助开展产品培训、使用指导和技术答疑，帮助科研用户快速了解并使用平台，持续优化用户体验；\n4、参与策划和执行用户活跃、留存及产品推广活动，包括内容撰写、用户触达、线上活动和校园推广等；\n5、协助建设和维护高校微信群、QQ 课题组群及学科垂直社群，参与社群日常运营，提升用户活跃度与粘性；","requirements":"1、本科或研究生在读，计算机、人工智能、生物学、化学、材料科学等理工科专业优先；\n2、对科研工作场景有一定了解，有实验室、课题组或科研项目经历者优先；\n3、对 AI 产品及前沿技术有浓厚兴趣，愿意主动体验产品并快速学习相关知识；\n4、具备良好的沟通表达和文字撰写能力，能够耐心倾听并协助解决用户问题；\n5、做事认真细致，有较强的执行力、责任心和团队协作意识，能够主动推进工作；\n6、有校园社群运营、新媒体运营、活动策划、产品运营或用户调研经验者优先；\n7、连续实习 3 个月及以上，能够长期稳定实习者优先。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab:7676049497369348394","sourceKey":"shlab","company":"上海AI实验室","title":"【实习】医学多模态模型/手术智能/医疗智能体-医学智能中心","city":"上海","category":"","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7676049497369348394?mode=campus","duty":"上海人工智能实验室医疗中心医学智能探索组团队现面向国内外高校招募研究实习生，共同探索医学人工智能领域具有长期价值和临床转化潜力的前沿问题。围绕医学多模态基础模型、手术智能与医疗智能体展开，希望连接医学影像、临床知识、解剖结构、手术视频与机器人动作，构建能够真正理解医学场景、辅助临床决策并参与复杂任务执行的多模态基础模型与智能系统。\n\n主要研究方向：\n1. 医学多模态模型\n研究如何统一建模三维医学影像、手术视频、医学文本、解剖结构及拓扑知识，包括但不限于：\n1）医学视觉—语言基础模型与多模态推理；三维医学影像基础模型及高效适配；\n2）医学图像、报告与结构化知识的联合建模；解剖结构感知、拓扑推理与空间关系理解；\n3）医学多模态数据构建、指令微调与评测体系；基础模型在真实临床任务中的泛化、可信与安全问题。\n\n2. 手术智能与具身医疗智能\n面向各类微创介入等场景，研究从手术感知到导航、决策和自主操","requirements":"1、就读于计算机、人工智能、自动化、生物医学工程、电子信息、机器人或相关专业的大三及以上的本科生/硕士生/博士生；\n2、具备扎实的深度学习基础，熟悉 PyTorch 等训练框架；\n3、对计算机视觉、多模态大模型、医学影像、机器人或智能体中的至少一个方向有深入兴趣；\n\n团队在医学影像分析、解剖结构建模、医学基础模型与手术机器人智能方面具有持续积累。相关研究成果已发表于或录用于：NEJM AI、npj Digital Medicine、Medical Image Analysis、IEEE Transactions on Medical Imaging、IEEE Journal of Biomedical and Health Informatics、MICCAI、IPCAI 等高水平期刊与会议。目前另有多项研究工作正在 Nature Machine Intelligence、Nature C","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab:7676089891314518298","sourceKey":"shlab","company":"上海AI实验室","title":"【实习】非洲区域研究-数据平台中心","city":"上海","category":"","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7676089891314518298?mode=campus","duty":"1. 深度参与斯瓦希里语、南非荷兰语多模态 AI 数据集建设全流程，围绕对象国政治、经济、社会、历史、文化、宗教、外交及安全等领域，协助推进研究框架设计、数据标准制定、进度管理和质量验收。\n2. 结合对象国实际情况及所在区域特征，协助建设和优化国别知识体系、数据标签体系、实体与事件分类体系、验收规范及质量标准。\n3. 根据项目需求开展多语种资料搜集、信息抽取、交叉验证和结构化整理，能够从对象国语言材料及权威来源中提取有效信息，并对数据的真实性、准确性、时效性和来源可靠性进行判断。\n4. 参与数据的抽样验收和质量评估，识别事实错误、语义偏差、时空关系错误、实体混淆、文化适配问题及区域认知偏差，并推动问题修正。\n5. 围绕对象国的重要机构、人物、政策、产业、社会议题和国际关系开展专题研究，为大模型训练、评测及相关 AI 产品提供知识支持。\n6. 跟踪对象国及相关区域的重要动态，协助沉淀知识库、","requirements":"1. 硕士及以上学历在读，国别区域研究、外语语言文学、国际关系等相关专业优先。\n2. 具备以下研究方向的专业背景：非洲区域研究。\n3. 熟练掌握斯瓦希里语和南非荷兰语中的一种语言，能够阅读和理解对象国新闻、政府文件、研究报告、学术文献及互联网资料；具备良好的中文信息归纳和写作能力。\n4. 对对象国的政治制度、经济结构、社会文化、历史发展、宗教民族、外交关系等至少一个领域有较深入了解，能够识别资料中的事实错误、文化偏差及语境差异。\n5. 具备较强的资料检索、信源判断、事实核查、信息抽取和结构化整理能力，能够对多来源信息进行交叉验证。\n6. 熟悉常见办公工具，具有较好的数据敏感度；了解结构化信息抽取、知识图谱、数据标注、大模型训练评测或 AI 产品者优先。\n实习要求：每周实习3—4天，全勤优先；需连续实习3个月及以上。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab:7676090693576706313","sourceKey":"shlab","company":"上海AI实验室","title":"【实习】东南亚区域研究-数据平台中心","city":"上海","category":"","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7676090693576706313?mode=campus","duty":"1. 深度参与缅甸语多模态 AI 数据集建设全流程，围绕对象国政治、经济、社会、历史、文化、宗教、外交及安全等领域，协助推进研究框架设计、数据标准制定、进度管理和质量验收。\n2. 结合对象国实际情况及所在区域特征，协助建设和优化国别知识体系、数据标签体系、实体与事件分类体系、验收规范及质量标准。\n3. 根据项目需求开展多语种资料搜集、信息抽取、交叉验证和结构化整理，能够从对象国语言材料及权威来源中提取有效信息，并对数据的真实性、准确性、时效性和来源可靠性进行判断。\n4. 参与数据的抽样验收和质量评估，识别事实错误、语义偏差、时空关系错误、实体混淆、文化适配问题及区域认知偏差，并推动问题修正。\n5. 围绕对象国的重要机构、人物、政策、产业、社会议题和国际关系开展专题研究，为大模型训练、评测及相关 AI 产品提供知识支持。\n6. 跟踪对象国及相关区域的重要动态，协助沉淀知识库、研究报告等数据资","requirements":"1. 硕士及以上学历在读，国别区域研究、外语语言文学、国际关系等相关专业优先。\n2. 具备以下研究方向的专业背景：东南亚区域研究。\n3. 熟练掌握缅甸语，能够阅读和理解对象国新闻、政府文件、研究报告、学术文献及互联网资料；具备良好的中文信息归纳和写作能力。\n4. 对对象国的政治制度、经济结构、社会文化、历史发展、宗教民族、外交关系等至少一个领域有较深入了解，能够识别资料中的事实错误、文化偏差及语境差异。\n5. 具备较强的资料检索、信源判断、事实核查、信息抽取和结构化整理能力，能够对多来源信息进行交叉验证。\n6. 熟悉常见办公工具，具有较好的数据敏感度；了解结构化信息抽取、知识图谱、数据标注、大模型训练评测或 AI 产品者优先。\n\n实习要求：每周实习3—4天，全勤优先；需连续实习3个月及以上。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab:7676090704138193161","sourceKey":"shlab","company":"上海AI实验室","title":"【实习】欧洲区域研究-数据平台中心","city":"上海","category":"","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7676090704138193161?mode=campus","duty":"1. 深度参与西班牙语多模态 AI 数据集建设全流程，围绕对象国政治、经济、社会、历史、文化、宗教、外交及安全等领域，协助推进研究框架设计、数据标准制定、进度管理和质量验收。\n2. 结合对象国实际情况及所在区域特征，协助建设和优化国别知识体系、数据标签体系、实体与事件分类体系、验收规范及质量标准。\n3. 根据项目需求开展多语种资料搜集、信息抽取、交叉验证和结构化整理，能够从对象国语言材料及权威来源中提取有效信息，并对数据的真实性、准确性、时效性和来源可靠性进行判断。\n4. 参与数据的抽样验收和质量评估，识别事实错误、语义偏差、时空关系错误、实体混淆、文化适配问题及区域认知偏差，并推动问题修正。\n5. 围绕对象国的重要机构、人物、政策、产业、社会议题和国际关系开展专题研究，为大模型训练、评测及相关 AI 产品提供知识支持。\n6. 跟踪对象国及相关区域的重要动态，协助沉淀知识库、研究报告等数据","requirements":"1. 硕士及以上学历在读，国别区域研究、外语语言文学、国际关系等相关专业优先。\n2. 具备以下研究方向的专业背景：欧洲区域研究。\n3. 熟练掌握西班牙语，能够阅读和理解对象国新闻、政府文件、研究报告、学术文献及互联网资料；具备良好的中文信息归纳和写作能力。\n4. 对对象国的政治制度、经济结构、社会文化、历史发展、宗教民族、外交关系等至少一个领域有较深入了解，能够识别资料中的事实错误、文化偏差及语境差异。\n5. 具备较强的资料检索、信源判断、事实核查、信息抽取和结构化整理能力，能够对多来源信息进行交叉验证。\n6. 熟悉常见办公工具，具有较好的数据敏感度；了解结构化信息抽取、知识图谱、数据标注、大模型训练评测或 AI 产品者优先。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab:7676090704158378278","sourceKey":"shlab","company":"上海AI实验室","title":"【实习】拉丁美洲区域研究-数据平台中心","city":"上海","category":"","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7676090704158378278?mode=campus","duty":"1. 深度参与葡萄牙语多模态 AI 数据集建设全流程，围绕对象国政治、经济、社会、历史、文化、宗教、外交及安全等领域，协助推进研究框架设计、数据标准制定、进度管理和质量验收。\n2. 结合对象国实际情况及所在区域特征，协助建设和优化国别知识体系、数据标签体系、实体与事件分类体系、验收规范及质量标准。\n3. 根据项目需求开展多语种资料搜集、信息抽取、交叉验证和结构化整理，能够从对象国语言材料及权威来源中提取有效信息，并对数据的真实性、准确性、时效性和来源可靠性进行判断。\n4. 参与数据的抽样验收和质量评估，识别事实错误、语义偏差、时空关系错误、实体混淆、文化适配问题及区域认知偏差，并推动问题修正。\n5. 围绕对象国的重要机构、人物、政策、产业、社会议题和国际关系开展专题研究，为大模型训练、评测及相关 AI 产品提供知识支持。\n6. 跟踪对象国及相关区域的重要动态，协助沉淀知识库、研究报告等数据","requirements":"1. 硕士及以上学历在读，国别区域研究、外语语言文学、国际关系等相关专业优先。\n2. 具备以下研究方向的专业背景：拉丁美洲研究。\n3. 熟练掌握巴西葡萄牙语，能够阅读和理解对象国新闻、政府文件、研究报告、学术文献及互联网资料；具备良好的中文信息归纳和写作能力。\n4. 对对象国的政治制度、经济结构、社会文化、历史发展、宗教民族、外交关系等至少一个领域有较深入了解，能够识别资料中的事实错误、文化偏差及语境差异。\n5. 具备较强的资料检索、信源判断、事实核查、信息抽取和结构化整理能力，能够对多来源信息进行交叉验证。\n6. 熟悉常见办公工具，具有较好的数据敏感度；了解结构化信息抽取、知识图谱、数据标注、大模型训练评测或 AI 产品者优先。\n\n实习要求：每周实习3—4天，全勤优先；需连续实习3个月及以上。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab:7676111486607509806","sourceKey":"shlab","company":"上海AI实验室","title":"【实习】AI×有机合成研究-数据平台中心","city":"上海","category":"","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7676111486607509806?mode=campus","duty":"上海人工智能创新中心正在构建基于 AI 的多步逆合成路径规划系统。团队已具备完整的 AI 建模与工程迭代能力，现需招募具备有机合成专业背景的在校研究生（硕士/博士），以实习生身份参与 AI 逆合成系统的路线评估与研发迭代工作。\n你将运用自己的合成化学训练，对 AI 生成的多步合成路线进行专业评估与深度分析，并在此过程中为 AI 系统的持续改进提供来自化学视角的关键反馈。你的评估不只是\"打分\"——它将直接驱动模型的错误归因、评估标准的演进和系统能力的提升。这是一个将有机合成专业能力与前沿 AI 研究深度结合的实习机会。\n（本岗位不涉及湿实验操作，不要求编程基础。）\n\n核心工作内容\n一、逆合成路线质量评估\n- 阅读 AI 系统生成的多步合成路线（含每一步的反应类型、试剂条件、产物结构等）\n- 按项目评估规范，对整条路线与每一步反应进行系统化评估\n- 标记不合理的反应步骤，简要说明问题所在（如条","requirements":"- 在校硕士或博士研究生，有机化学相关方向（药物合成、全合成、有机方法学、工艺研发等）\n- 具备有机合成实际实验训练，在课题研究中参与过多步合成路线的设计或执行（非纯计算/理论方向）\n- 能够基于真实合成经验判断多步路线的整体可行性，而不仅是理解单步反应机理\n- 熟悉常见有机合成反应类型、保护基策略、选择性问题和官能团兼容性问题\n- 能够阅读英文合成文献，理解反应方案、条件筛选表和底物拓展表\n- 工作细致，对评估质量有责任感，能用简洁清晰的文字说明判断理由\n- 每周可投入 ≥ 3 天，能保持至少 3 个月的持续参与\n  \n优先录用\n- 博士生优先，尤其是课题涉及多步全合成或药物分子合成者\n- 有完整合成项目经验者优先（课题中完成过 5 步以上合成路线）\n- 有多步合成路线可行性评估、反应条件筛选、底物拓展或工艺优化经验者优先\n- 了解逆合成分析的基本思路与策略\n- 对 AI for Che","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab:7677801884031584518","sourceKey":"shlab","company":"上海AI实验室","title":"【实习】AI 产品经理实习生（生物/材料/化学方向）-产品规划中心","city":"上海","category":"","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7677801884031584518?mode=campus","duty":"1、协助梳理生物、材料、化学场景下的用户需求，参与产品需求文档（PRD）撰写\n2、参与 AI 产品的功能设计与原型绘制，协助跟进研发进度\n3、收集并整理用户反馈，协助完成竞品调研与行业分析报告\n4、配合产品经理完成日常产品迭代任务，推动跨团队沟通协作","requirements":"1、在读学历：本科大三及以上 / 硕士在读，生物、材料、化学、生物信息学或相关理工科专业\n2、实习时长：每周至少 4 天，可实习 3 个月以上优先\n3、基本能力：\n1）逻辑清晰，善于结构化表达，文档撰写能力强\n2）对 AI 技术有基本认知，了解大模型、机器学习等概念\n3）熟练使用 Office/飞书 等协作工具；会 Axure/Figma 者加分\n4）学习意愿强，能在快节奏环境中主动推进任务\n\n加分项\n1、有科研经历（课题组 / 竞赛 / 论文），理解实验室工作流程\n2、了解生物信息、计算化学、材料模拟等方向\n3、有产品、用户研究相关实习经历","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab:7677802141684467987","sourceKey":"shlab","company":"上海AI实验室","title":"【实习】后端开发实习生（AI Infra / LLM Gateway）-技术平台中心","city":"上海","category":"","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7677802141684467987?mode=campus","duty":"1. 参与 LLM API Gateway 的后端开发，支持 OpenAI Chat Completions、Anthropic Messages 等协议兼容。\n2. 参与 API Key 鉴权、项目模型白名单、限流、余额预检、并发控制等网关能力建设。\n3. 编写接口文档、单元测试、协议兼容测试和基础压测脚本，保障核心链路稳定性。\n4. 协助排查线上调用失败、流式响应异常、usage 不一致、供应商错误码差异等工程问题。\n","requirements":"1. 计算机相关专业本科或研究生在读，每周可实习 4 天及以上，连续实习 3 个月以上优先。\n2. 熟悉至少一门后端语言，如 Go、Python、Java、Node.js，具备良好的编码习惯。\n3. 理解 HTTP、RESTful API、SSE 流式响应、鉴权、限流、超时、重试等后端基础概念。\n4. 熟悉 MySQL / PostgreSQL、Redis、消息队列中的一种或多种。\n5. 具备基本的并发编程、异步任务、日志排查和接口测试能力。\n6. 对大模型 API、OpenAI SDK、Anthropic API、Prompt、Token usage 等概念有了解或强兴趣。\n\n加分项：\n1. 有 API Gateway、计费系统、SaaS 后台、多租户系统、开发者平台相关项目经验。\n2. 熟悉 Go 语言，或有高并发服务、微服务、Kubernetes 相关实践。\n3. 使用过 OpenA","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab:7677804403931728179","sourceKey":"shlab","company":"上海AI实验室","title":"【实习】大模型&智能体安全实习生-攻防平台中心","city":"上海","category":"","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7677804403931728179?mode=campus","duty":"1、紧跟学术界与工业界在安全领域的最新动态（如 Agent Safety, Jailbreak, Prompt Injection, Adversarial Attacks 等），阅读并快速复现相关论文中的攻击与防御算法。\n2、设计并构造针对大模型的多样化攻击提示词和对抗样本，对模型进行红队测试（Red Teaming），分析模型在恶意诱导下的脆弱性及失效模式。\n3、参与大模型及智能体安全检测的系统构建与算法落地，实现从环境构建、自动化攻击到安全校验的全流程工程化闭环。","requirements":"1、计算机、人工智能、网络安全、数学等相关专业在读硕士/博士，基础扎实的优秀本科生亦可。\n2、精通 Python 编程，具备良好的代码风格；熟悉 PyTorch 或 TensorFlow 等主流深度学习框架，熟练使用 HuggingFace Transformers 库进行模型调用与推理。\n3、理解 Transformer 架构、LLM 的训练与微调基本原理；对提示工程有一定实践经验。\n4、对 AI 安全、对抗性机器学习（Adversarial ML）有浓厚兴趣；具备快速学习能力，能阅读英文顶会论文并转化为代码。\n5、每周出勤3天以上，连续实习 3 个月以上（长期实习者优先）。\n\n加分项：\n1、熟悉常见的 LLM 攻击模式（如 GCG, AutoDAN, PAIR 等）或防御机制（如 PPO, DPO, Guardrails）。\n2、在 AI 安全、NLP 等领域的顶级会议（NeurIPS","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab:7677805722134432063","sourceKey":"shlab","company":"上海AI实验室","title":"【实习】大模型评测实习生-大模型中心","city":"上海","category":"","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7677805722134432063?mode=campus","duty":"1、评测体系构建：参与设计并执行文本、多模态大模型及智能体的评测框架设计，构建覆盖多场景的评测基准（Benchmark），并持续优化评测流程的效率与可靠性。\n2、技术探索与集成：跟踪学术界与工业界的最新大模型及智能体评测方法与评测 benchmark，快速将其集成到现有平台。\n3、评测结果分析：与大模型算法团队紧密协作，从评测结果中分析模型及智能体能力瓶颈，用于公开榜单与内部模型能力迭代。\n4、跟踪AI领域前沿技术，团队协作，完成算法评测相关科研任务。","requirements":"1、计算机、人工智能或相关专业硕士及以上学历，具备算法理论基础。\n2、具备丰富的大模型或 Agent 算法评测经验，熟悉其相关评测方法。\n3、熟悉Python、GIt 等开发工具，了解 LLM、MLLM、Agent 部署等，了解自动化测试流程，了解容器化、沙盒、网络通信等。\n4、在ACM/ICPC、Kaggle等编程或算法竞赛中获奖，或有开源项目贡献经验者优先。\n5、在ICLR、ICML、NeurIPS、ACL等顶会顶刊发表过论文者优先。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab:7677807281757866291","sourceKey":"shlab","company":"上海AI实验室","title":"【实习】AI物质科学实习生","city":"上海","category":"","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7677807281757866291?mode=campus","duty":"我们致力于探索人工智能的前沿，解决物质科学领域的重大挑战。在这里，你将与来自人工智能、计算机科学、物理学、化学和材料科学等领域专家共同工作，推动新材料的发现、物质性质的精准预测与科学规律的深度挖掘。 \n\n工作职责：\n1、参与机器学习与物质科学交叉研究项目，包括新算法设计、模型开发和训练等，并持续迭代以提升模型的准确性、效率与泛化能力；\n2、深入物质科学领域，定位并利用人工智能技术解决其中的关键瓶颈问题，如计算模拟、机理发现、合成工艺优化、自主实验室等；\n3、将研究成果应用于实际问题，在重大价值场景中实现落地。","requirements":"任职要求(实习)：\n1、人工智能或计算物理/化学/材料相关专业，硕士或博士在读，有扎实的理论基础，也欢迎优秀本科生； \n2、熟悉常见的机器学习势函数或大语言模型 ，有 AI for science 相关研究经验，发表过一作高质量学术论文； \n3、具有较强的代码能力，有高影响力开源项目经验优先； \n4、具备良好的英文阅读与写作能力、团队合作能力和沟通能力，能够快速掌握新技能；\n5、要求线下实习，长期实习优先。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab:7677836529562405130","sourceKey":"shlab","company":"上海AI实验室","title":"【实习】IT实习生-信息技术中心","city":"上海","category":"","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7677836529562405130?mode=campus","duty":"1、负责单位员工的IT桌面技术支持（Windows和Linux）工作，包括不限于软硬件维护报修；\n2、helpdesk服务号及时回复、账号建立及删除，保证员工电脑及办公软件正常使用；\n3、负责IT资产（电脑、办公设备软硬件、打印机）的管理，定期对IT固定资产盘点及追踪固定资产状态；\n4、会议室现场支持以及会议室日常巡检；\n5、负责入、离职流程的相关IT事务，包括不限于入职员工电脑配置、账号邮箱设置，离职员工电脑回收，系统重装数据清空等；\n6、负责机房的巡检、服务器的管理维护；路由器，交换机、无线AP、NAS的管理与配置；门禁、系统的维护，确保服务器及网络的正常；\n7、完善IT运维、信息化建设、制定相关IT制度；\n8、完成上级领导安排的其他工作。\n","requirements":"1、本科及以上，计算专业优先；\n2、实习期5个月以上，每周保证4天以上实习时间；\n3、熟练掌握Linux、Windows等操作系统者优先；\n4、良好的沟通技巧，思维清晰，善于表达，有良好的服务意识；\n5、良好的分析问题，桌面运维文档归纳与解决问题的能力；\n6、积极与乐观的态度。","description":"","jdComplete":true,"sourceStatus":"1"}];
